package com.dawnrise.school.announcement;
import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/releases") @PreAuthorize("@schoolTenantSecurity.hasOrganization(authentication)") public class TenantReleaseController {private final DawnriseReleaseService service;private final NotificationRecipientAccess access;public TenantReleaseController(DawnriseReleaseService service,NotificationRecipientAccess access){this.service=service;this.access=access;}@GetMapping("/{id}")public ReleaseDtos.View get(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){long org=((Number)jwt.getClaim("organizationId")).longValue();long user=Long.parseLong(jwt.getSubject());if(!access.allowed(org,user,"RELEASE_DETAILS",id))throw new com.dawnrise.school.school.exception.ResourceNotFoundException("Release not found");return service.getForOrganization(org,id);}}
